<?php require 'includes/functions.php';$u=auth();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(post('action')==='password'){$hash=q('SELECT password FROM users WHERE id=?',[$u['id']])->fetchColumn();if(!password_verify(post_raw('old_password'),$hash)||strlen(post_raw('password'))<12||strlen(post_raw('password'))>72||post_raw('password')!==post_raw('confirm'))throw new RuntimeException('รหัสผ่านเดิมไม่ถูกต้อง หรือรหัสผ่านใหม่ไม่ตรงกัน/ยาวไม่ถึง 12 ไบต์');q('UPDATE users SET password=? WHERE id=?',[password_hash(post_raw('password'),PASSWORD_DEFAULT),$u['id']]);session_regenerate_id(true);}else{if(post('name')===''||mb_strlen(post('name'))>120||mb_strlen(post('phone'))>30||mb_strlen(post('address'))>2000)throw new RuntimeException('กรุณาตรวจสอบความยาวข้อมูล');if(post('address')!==''&&post('address')!==($u['address']??'')&&!valid_delivery_map(post('address')))throw new RuntimeException('กรุณาวางลิงก์ Google Maps แบบ https จากเมนูแชร์ตำแหน่ง');db()->beginTransaction();q('UPDATE users SET name=?,phone=?,address=? WHERE id=?',[post('name'),post('phone'),post('address'),$u['id']]);q('INSERT INTO pdpa_consents(user_id,granted) VALUES (?,?)',[$u['id'],isset($_POST['marketing'])?1:0]);db()->commit();}flash('บันทึกข้อมูลสำเร็จ');go('profile.php');}catch(RuntimeException $ex){if(db()->inTransaction())db()->rollBack();$error=$ex->getMessage();}}
$consent=q('SELECT granted FROM pdpa_consents WHERE user_id=? ORDER BY id DESC LIMIT 1',[$u['id']])->fetchColumn();require 'includes/header.php';?><div class="page-heading"><h1><?=e(t('บัญชีของฉัน'))?></h1><a class="button secondary" href="<?=url('addresses.php')?>"><?=e(t('ที่อยู่ของฉัน'))?></a><p><?=e($u['email'])?></p></div><p class="error"><?=e(t($error))?></p><div class="two-col"><section class="panel"><h2><?=e(t('ข้อมูลส่วนตัว'))?></h2><form method="post"><?=csrf()?><?php field('name','ชื่อ–นามสกุล','text',$u['name']);field('phone','เบอร์ติดต่อ','tel',$u['phone'],false);?><p class="payment-help"><?=e(t('จัดการที่อยู่เต็มและที่อยู่เริ่มต้นได้ที่ “ที่อยู่ของฉัน” ช่องแผนที่เดิมด้านล่างเป็นข้อมูลสำรองเมื่อยังไม่ได้เลือกที่อยู่ที่บันทึกไว้'))?></p><label><?=e(t('ลิงก์แผนที่จัดส่งเดิม (Google Maps)'))?><input type="text" inputmode="url" name="address" maxlength="2000" placeholder="https://maps.app.goo.gl/..." value="<?=e($u['address'])?>"><small><?=e(t('เปิด Google Maps เลือกตำแหน่ง แล้วกดแชร์ → คัดลอกลิงก์'))?></small></label><?php if(valid_delivery_map($u['address']??'')): ?><p><?=delivery_location_html($u['address'])?></p><?php elseif(!empty($u['address'])): ?><p><small><?=e(t('ข้อมูลเดิมยังเก็บไว้ สามารถแทนด้วยลิงก์แผนที่เมื่อพร้อม'))?></small></p><?php endif ?><label class="checkbox"><input type="checkbox" name="marketing" <?=$consent?'checked':''?>> <?=e(t('รับข่าวสารและโปรโมชั่น (เอาเครื่องหมายออกเพื่อถอนความยินยอม)'))?></label><button><?=e(t('บันทึก'))?></button></form></section><section class="panel"><h2><?=e(t('เปลี่ยนรหัสผ่าน'))?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="password"><?php field('old_password','รหัสผ่านเดิม','password');field('password','รหัสผ่านใหม่ (12–72 ไบต์)','password');field('confirm','ยืนยันรหัสผ่านใหม่','password');?><button><?=e(t('เปลี่ยนรหัสผ่าน'))?></button></form></section></div><p><a href="my_orders.php"><?=e(t('คำสั่งซื้อของฉัน ↗'))?></a> · <a href="privacy_request.php"><?=e(t('คำขอข้อมูลส่วนบุคคล'))?></a></p><form method="post" action="logout.php"><?=csrf()?><button class="secondary"><?=e(t('ออกจากระบบ'))?></button></form><?php require 'includes/footer.php';?>
